def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    for r in range(h):
        for c in range(w):
            if r < w and c < h:
                a, b = out[r][c], out[c][r]
                if a == 0 and b != 0:
                    out[r][c] = b
                elif b == 0 and a != 0:
                    out[c][r] = a
    return out
